`,Se=`// 鈴老闆的嗆聲（世界觀聖經 §9.2）。英文是暫譯，在地化時再定稿。
{
  $schema: '../../schemas/strings.schema.json',
  items: [
    { id: 'taunt.enter.1', text: { 'zh-TW': '歡迎光臨冥途派遣，今晚加班費我出！', en: 'Welcome to Netherway Staffing. Overtime is on me tonight!' } },
    { id: 'taunt.enter.2', text: { 'zh-TW': '這麼晚還在值班？要不要考慮轉職？', en: 'Still on shift this late? Ever thought about a career change?' } },
    { id: 'taunt.enter.3', text: { 'zh-TW': '好兄弟，上工囉！', en: 'Brothers, clock in!' } },
    { id: 'taunt.wave.1', text: { 'zh-TW': '下一批員工到職！', en: 'Next batch of staff, reporting for work!' } },
    { id: 'taunt.wave.2', text: { 'zh-TW': '人手不夠？我這裡多的是！', en: 'Short-handed? I have plenty!' } },
    { id: 'taunt.wave.3', text: { 'zh-TW': '派遣合約，一次簽三十天喔！', en: 'Our contracts run thirty days, you know!' } },
    { id: 'taunt.level_up.1', text: { 'zh-TW': '喔？學會新招啦？我的員工也會加薪喔。', en: 'Oh? A new trick? My staff get raises too.' } },
    { id: 'taunt.level_up.2', text: { 'zh-TW': '升級很好，我也正在擴編。', en: 'Leveling up? Good. I am expanding too.' } },
    { id: 'taunt.level_up.3', text: { 'zh-TW': '進修精神可嘉，可惜沒有加班費。', en: 'Admirable training spirit. Shame there is no overtime pay.' } },
    { id: 'taunt.death.1', text: { 'zh-TW': '辛苦了，這份工作不適合你。', en: 'Good effort. This job just is not for you.' } },
    { id: 'taunt.death.2', text: { 'zh-TW': '要不要來我這裡上班？待遇比廟裡好。', en: 'Want to work for me? Better pay than the temple.' } },
    { id: 'taunt.death.3', text: { 'zh-TW': '下一個！', en: 'Next!' } },
    { id: 'taunt.decoy.1', text: { 'zh-TW': '打錯人了啦！那是我的分身。', en: 'Wrong guy! That was my double.' } },
    { id: 'taunt.decoy.2', text: { 'zh-TW': '紙錢很貴耶，你賠喔？', en: 'Paper money is not cheap. You paying for that?' } },
    { id: 'taunt.decoy.3', text: { 'zh-TW': '哈哈哈，本尊在這裡……騙你的。', en: 'Ha! The real me is over here... just kidding.' } },
  ],
}
